INSERT INTO fiches (prospect_id, takeaways, questions, model, origin, created_at) VALUES
  ('nordika-foods', '[{"text":"Nordika lance une gamme de yaourts végétaux **sans sucres ajoutés** en France au T1 2027.","source":"Communiqué de presse · 28 oct. 2026"},{"text":"Ils recrutent un·e **Flavour Development Manager** à Copenhague : le développement aromatique de la gamme n’est pas encore pourvu.","source":"Offre d’emploi LinkedIn · 4 nov. 2026"},{"text":"Leur rapport RSE fixe **-30 % de sucre d’ici 2028** sur toute la gamme, sans perte de goût.","source":"Rapport RSE 2025, p. 34"}]'::jsonb, '[{"text":"Quel profil de goût visez-vous pour compenser la baisse de sucre sans perdre en gourmandise ?","links":[1,3]},{"text":"Le développement aromatique sera-t-il fait en interne ou confié à un partenaire ?","links":[2]},{"text":"Quelles contraintes clean label ou bio s’appliquent au lancement en France ?","links":[1]},{"text":"Qui valide le choix du fournisseur : R&D, achats ou marketing ?","links":"contacts"}]'::jsonb, 'maquette (rédaction manuelle)', 'seed', '2026-11-10T09:00:00Z'),
  ('maison-lumen', '[{"text":"Maison Lumen prépare une **ligne soin corps** pour le printemps 2027.","source":"Interview du fondateur · Cosmétique Mag · 22 oct. 2026"},{"text":"Le poste de **Fragrance Development Manager** est ouvert à Lyon : le choix du parfumeur n’est pas fait.","source":"Offre d’emploi LinkedIn · 4 nov. 2026"}]'::jsonb, '[{"text":"Quelle signature olfactive voulez-vous pour la ligne soin corps ?","links":[1]},{"text":"Le futur Fragrance Development Manager choisira-t-il le parfumeur ?","links":[2]}]'::jsonb, 'maquette (rédaction manuelle)', 'seed', '2026-11-10T09:00:00Z'),
  ('velia-beverages', '[{"text":"Vélia Beverages prépare son expansion industrielle.","source":"Fiche entreprise"},{"text":"L''entreprise envisage une production doublée en 2027.","source":"Il Sole 24 Ore · 15 oct. 2026"},{"text":"Une usine à Milan est planifiée pour 2027.","source":"Synthèse des signaux"}]'::jsonb, '[{"text":"Quels sont les principaux goûts et saveurs que Vélia Beverages souhaite développer ?","links":[1]},{"text":"Comment Givaudan peut-il aider à améliorer la formulation des boissons de Vélia?","links":[2,3]},{"text":"Quelles réglementations spécifiques doit Vélia Beverages prendre en compte pour son expansion industrielle ?","links":[1]},{"text":"Avez-vous des prévisions sur le calendrier de cette nouvelle usine à Milan ?","links":[2,3]}]'::jsonb, 'qwen2.5:3b', 'seed', '2026-11-12T17:55:00.529Z'),
  ('brava-snacks', '[{"text":"Brava Snacks doit réduire le sel sur ses chips d''ici 2027.","source":"Fiche entreprise"},{"text":"Historiquement, Brava Snacks n''a pas travaillé avec Givaudan.","source":"Historique Givaudan"},{"text":"La réduction du sel est une obligation réglementaire pour l''entreprise.","source":"Ministère de l’Agriculture · 6 nov. 2026"}]'::jsonb, '[{"text":"Quels sont les principaux goûts que Brava Snacks souhaite apporter à ses produits ?","links":[1]},{"text":"Comment Givaudan peut-il aider Brava Snacks à respecter l''obligation de réduction du sel?","links":[2,3]},{"text":"Quelles sont les contraintes réglementaires liées au sel que Brava Snacks doit prendre en compte ?","links":[3]},{"text":"Comment peut-on définir un calendrier précis pour la mise en œuvre de cette réduction du sel?","links":[1]}]'::jsonb, 'qwen2.5:3b', 'seed', '2026-11-12T17:55:24.714Z'),
  ('atelier-seve', '[{"text":"L''entreprise a besoin d''étoffer sa gamme naturelle.","source":"L’Echo · 22 oct. 2026"},{"text":"Levée de fonds récente pour développer son offre.","source":"Synthèse des signaux"},{"text":"Givaudan n''a pas travaillé avec eux auparavant.","source":"Historique Givaudan"}]'::jsonb, '[{"text":"Quels soins naturels souhaitent-ils ajouter à leur gamme ?","links":[1]},{"text":"Comment peuvent-ils intégrer ces nouveaux produits dans leurs processus de fabrication ?","links":[2]},{"text":"Quelles réglementations spécifiques doivent-ils prendre en compte pour les cosmétiques naturels ?","links":[1]},{"text":"Avez-vous des suggestions sur comment augmenter leur portée locale avec ces nouveaux produits ?","links":[2]}]'::jsonb, 'qwen2.5:3b', 'seed', '2026-11-12T17:55:43.697Z'),
  ('kora-dairy', '[{"text":"Kora Dairy recherche une collaboration pour des produits laitiers.","source":"Fiche entreprise"},{"text":"La bonne adéquation de Kora Dairy avec les produits laitiers est un élément clé.","source":"Synthèse des signaux"},{"text":"Kora Dairy n''a pas d''expérience précédente avec Givaudan.","source":"Historique Givaudan"}]'::jsonb, '[{"text":"Quels sont les produits laitiers que Kora Dairy souhaite développer ?","links":[1,2]},{"text":"Kora Dairy a-t-elle des préoccupations spécifiques en matière de réglementation pour ces nouveaux produits ?","links":[3]},{"text":"Quel calendrier envisagez-vous pour commencer ce partenariat avec Givaudan?","links":[1,2,3]},{"text":"Kora Dairy a-t-elle des besoins en matière de goûts ou de formulations spécifiques ?","links":[1,2,3]}]'::jsonb, 'qwen2.5:3b', 'seed', '2026-11-12T17:56:05.988Z'),
  ('lys-co', '[{"text":"Nouvelle direction chez Lys & Co.","source":"Les Échos · 18 sept. 2026"},{"text":"Parfums d''intérieur, PACA","source":"Fiche entreprise"},{"text":"Changement de cap depuis septembre avec nouvelle directrice générale","source":"Synthèse des signaux"}]'::jsonb, '[{"text":"Quels sont les principaux changements apportés par la nouvelle direction ?","links":[1,3]},{"text":"Comment Givaudan peut-il s''adapter aux nouvelles orientations de Lys & Co?","links":[1,2,3]},{"text":"Quels sont les défis spécifiques liés à la nouvelle direction pour Lys & Co ?","links":[1,3]},{"text":"Comment Givaudan peut-il aider Lys & Co dans sa stratégie de développement?","links":[1,2,3]}]'::jsonb, 'qwen2.5:3b', 'seed', '2026-11-12T17:56:27.058Z'),
  ('hestia-bakery', '[{"text":"Taste & Wellbeing a une bonne portée régionale.","source":"Fiche entreprise"},{"text":"La taille de l''entreprise est adéquate pour la boulangerie industrielle.","source":"Fiche entreprise"},{"text":"Il n''y a pas eu de contact récent avec Givaudan.","source":"Historique Givaudan"}]'::jsonb, '[{"text":"Quels sont vos principaux produits actuels ?","links":[1]},{"text":"Comment évolue votre portée régionale ?","links":[1]},{"text":"Pourquoi avez-vous choisi de travailler avec Taste & Wellbeing?","links":[1]},{"text":"Quelles sont vos préoccupations en matière de goûts et d''arômes ?","links":[1,3]}]'::jsonb, 'qwen2.5:3b', 'seed', '2026-11-12T17:56:46.365Z'),
